import React from 'react';
import {Composition} from 'remotion';
import {Film, type Timeline} from './Film';
import {FONT_FAMILY, loadInter} from './fonts/inter';
import {buildTimeline} from './lib/timeline.mjs';
// Generated by scripts/render.mjs from output/guide-video/narration/timings.json.
import timings from './timings.generated.json';

// Module scope: the render is held until the vendored face is ready.
loadInter();

const timeline = (name: 'intro' | 'walkthrough') => buildTimeline((timings as any).videos[name]) as Timeline;

export const RemotionRoot: React.FC = () => {
  const intro = timeline('intro');
  const walkthrough = timeline('walkthrough');
  return (
    <>
      <Composition
        id="Intro"
        component={Film}
        durationInFrames={intro.durationInFrames}
        fps={intro.fps}
        width={1920}
        height={1080}
        defaultProps={{
          timeline: intro,
          kind: 'intro' as const,
          showBadge: false,
          fontFamily: FONT_FAMILY,
        }}
      />
      <Composition
        id="Walkthrough"
        component={Film}
        durationInFrames={walkthrough.durationInFrames}
        fps={walkthrough.fps}
        width={1920}
        height={1080}
        defaultProps={{
          timeline: walkthrough,
          kind: 'walkthrough' as const,
          showBadge: true,
          fontFamily: FONT_FAMILY,
        }}
      />
    </>
  );
};
